    "html": "\u003csection class=\"syn-root syn-region\" data-syn-theme=\"studio\" aria-labelledby=\"syn-bento-title\">\n  \u003cheader>\u003cp class=\"syn-eyebrow\">WHY TEAMS CHOOSE US\u003c/p>\u003ch2 id=\"syn-bento-title\" class=\"syn-heading\">One clear place to get work done\u003c/h2>\n    \u003cp class=\"syn-muted\">A container-aware bento layout built from ordinary semantic cards.\u003c/p>\u003c/header>\n  \u003cdiv class=\"syn-bento-grid\">\n    \u003carticle class=\"syn-feature-card syn-surface--accent syn-bento-card--wide\">\n      \u003cp class=\"syn-eyebrow\">VISIBILITY\u003c/p>\u003ch3>See the complete picture\u003c/h3>\n      \u003cp>Combine your pipeline, project milestones and operational signals without hopping between tools.\u003c/p>\n      \u003cdl class=\"syn-record-fields\">\u003cdiv>\u003cdt>Open projects\u003c/dt>\u003cdd>24 (sample)\u003c/dd>\u003c/div>\n        \u003cdiv>\u003cdt>Items needing review\u003c/dt>\u003cdd>3 (sample)\u003c/dd>\u003c/div>\u003c/dl>\n      \u003ca href=\"/features/overview\">Explore the overview\u003c/a>\n    \u003c/article>\n    \u003carticle class=\"syn-feature-card\">\u003cp class=\"syn-eyebrow\">SECURITY\u003c/p>\u003ch3>Know who can do what\u003c/h3>\n      \u003cp>Organize members and workspaces with clear permissions.\u003c/p>\u003ca href=\"/features/permissions\">Learn about access\u003c/a>\u003c/article>\n    \u003carticle class=\"syn-feature-card\">\u003cp class=\"syn-eyebrow\">AUTOMATION\u003c/p>\u003ch3>Make repeat work simpler\u003c/h3>\n      \u003cp>Present each workflow step and its owner in context.\u003c/p>\u003ca href=\"/features/automation\">Explore workflows\u003c/a>\u003c/article>\n    \u003carticle class=\"syn-feature-card\">\u003cp class=\"syn-eyebrow\">REPORTING\u003c/p>\u003ch3>Share results with clarity\u003c/h3>\n      \u003cp>Prepare actionable summaries that make sense to every stakeholder.\u003c/p>\u003ca href=\"/features/analytics\">Explore analytics\u003c/a>\u003c/article>\n  \u003c/div>\n\u003c/section>",
