    "id": "block-hero-product-preview",
    "title": "Product screenshot hero",
    "module": "syntyr.core.css + syntyr.recipes.css",
    "description": "Split-screen product hero with semantic CSS-only mock dashboard content.",
    "html": "\u003csection class=\"syn-root syn-region\" data-syn-theme=\"studio\" aria-labelledby=\"syn-hero-preview-title\">\n  \u003cdiv class=\"syn-showcase\">\n    \u003cdiv class=\"syn-showcase-copy\">\n      \u003cp class=\"syn-eyebrow\">A SIMPLER WAY TO OPERATE\u003c/p>\n      \u003ch2 id=\"syn-hero-preview-title\" class=\"syn-fluid-display\">Your work, finally in focus.\u003c/h2>\n      \u003cp class=\"syn-lede\">Plan work, keep stakeholders aligned and understand what happens next from one calm workspace.\u003c/p>\n      \u003cdiv class=\"syn-actions\">\u003ca class=\"syn-button syn-button--primary\" href=\"/start\">Start free\u003c/a>\n        \u003ca class=\"syn-button syn-button--outline\" href=\"/demo\">See the demo\u003c/a>\u003c/div>\n      \u003cp class=\"syn-caption\">Illustrative product presentation, not a live dashboard.\u003c/p>\n    \u003c/div>\n    \u003cdiv class=\"syn-showcase-visual\" role=\"region\" aria-label=\"Illustrative product dashboard\">\n      \u003cdiv class=\"syn-app-card\">\n        \u003cheader class=\"syn-app-card-header\">\u003ch3>Operations overview\u003c/h3>\u003cspan class=\"syn-badge\">Example\u003c/span>\u003c/header>\n        \u003cdiv class=\"syn-kpi-grid\">\n          \u003cdiv class=\"syn-panel\">\u003cp class=\"syn-caption\">Active projects\u003c/p>\u003cstrong>24\u003c/strong>\u003c/div>\n          \u003cdiv class=\"syn-panel\">\u003cp class=\"syn-caption\">Pending review\u003c/p>\u003cstrong>3\u003c/strong>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"syn-table-wrap\" role=\"region\" tabindex=\"0\" aria-label=\"Illustrative dashboard records, scroll for more columns\">\n          \u003ctable class=\"syn-table syn-table--readable\">\u003ccaption>Recent work (sample data)\u003c/caption>\n            \u003cthead>\u003ctr>\u003cth scope=\"col\">Workstream\u003c/th>\u003cth scope=\"col\">Owner\u003c/th>\u003cth scope=\"col\">State\u003c/th>\u003c/tr>\u003c/thead>\n            \u003ctbody>\u003ctr>\u003cth scope=\"row\">Website release\u003c/th>\u003ctd>Design\u003c/td>\u003ctd>In review\u003c/td>\u003c/tr>\n              \u003ctr>\u003cth scope=\"row\">Customer onboarding\u003c/th>\u003ctd>Operations\u003c/td>\u003ctd>Active\u003c/td>\u003c/tr>\u003c/tbody>\n          \u003c/table>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/div>\n\u003c/section>",
